content:
:root {
  --bg-primary: #f8fafc;
  --bg-surface: #ffffff;
  --bg-subtle: #f1f5f9;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --text-light: #94a3b8;
  --accent-primary: #3b82f6;
  --accent-primary-hover: #2563eb;
  --accent-danger: #ef4444;
  --accent-danger-hover: #dc2626;
  --border-color: #e2e8f0;
  --border-focus: #3b82f6;
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-full: 9999px;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --transition-fast: 0.15s ease;
  --transition-normal: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-primary);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* アプリ全体コンテナ */
.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 16px 48px;
  display: flex;
  flex-direction: column;
  gap: 24px;
  min-height: 100vh;
}

/* ヘッダーセクション */
.header {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding-bottom: 8px;
}

.header-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.02em;
  display: flex;
  align-items: center;
  gap: 8px;
}

.header-subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
}

/* 合計金額カード */
.total-card {
  background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%);
  color: #ffffff;
  padding: 24px;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  gap: 6px;
  position: relative;
  overflow: hidden;
}

.total-card::after {
  content: "";
  position: absolute;
  top: -40px;
  right: -40px;
  width: 140px;
  height: 140px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(59, 130, 246, 0.2) 0%, rgba(59, 130, 246, 0) 70%);
  pointer-events: none;
}

.total-label {
  font-size: 0.9rem;
  font-weight: 500;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.total-amount {
  font-size: 2.5rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: #ffffff;
  display: flex;
  align-items: baseline;
  gap: 4px;
}

@media (max-width: 480px) {
  .total-amount {
    font-size: 1.85rem;
  }
}

/* メインレイアウト */
.main-layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
  align-items: start;
}

@media (min-width: 900px) {
  .main-layout {
    grid-template-columns: 1.15fr 1fr;
  }
}

/* グラフセクション */
.chart-section {
  display: flex;
  flex-direction: column;
  gap: 16px;
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
}

.chart-wrapper {
  width: 100%;
  height: 320px;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  outline: none;
}

.hint-text {
  font-size: 0.85rem;
  color: var(--text-muted);
  text-align: center;
  margin-top: -4px;
}

/* 選択された項目の情報カード */
.selected-info-card {
  background-color: var(--bg-subtle);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: all var(--transition-fast);
}

.selected-info-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.selected-name {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-main);
  display: flex;
  align-items: center;
  gap: 8px;
}

.selected-amount {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--text-main);
}

.selected-empty-text {
  font-size: 1rem;
  color: var(--text-muted);
}

.selected-ratio {
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  font-size: 0.85rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  background-color: #ffffff;
  color: var(--accent-primary);
  border: 1px solid var(--border-color);
}

/* リストセクション */
.list-section {
  display: flex;
  flex-direction: column;
  gap: 16px;
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
}

.list-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.list-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-main);
}

.expense-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-height: 480px;
  overflow-y: auto;
  padding-right: 4px;
}

.expense-list::-webkit-scrollbar {
  width: 6px;
}

.expense-list::-webkit-scrollbar-track {
  background: transparent;
}

.expense-list::-webkit-scrollbar-thumb {
  background: var(--border-color);
  border-radius: var(--radius-full);
}

.expense-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: transform var(--transition-fast), border-color var(--transition-fast), background-color var(--transition-fast), box-shadow var(--transition-fast);
  gap: 12px;
  position: relative;
  user-select: none;
  outline: none;
}

.expense-card:hover {
  border-color: #cbd5e1;
  background-color: #f8fafc;
  transform: translateY(-1px);
}

.expense-card:focus-visible {
  outline: 2px solid var(--accent-primary);
  outline-offset: 2px;
}

.expense-card-active {
  border-color: var(--accent-primary);
  background-color: #eff6ff;
  box-shadow: 0 0 0 1px var(--accent-primary);
}

.expense-card-active:hover {
  background-color: #eff6ff;
}

.expense-icon-badge {
  width: 40px;
  height: 40px;
  min-width: 40px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  background-color: var(--bg-subtle);
}

.expense-details {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  gap: 2px;
}

.expense-name {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-main);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.expense-amount {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-main);
}

.expense-ratio {
  font-size: 0.8rem;
  color: var(--text-muted);
  font-weight: 500;
}

.expense-delete-btn {
  background: transparent;
  border: none;
  color: var(--text-light);
  cursor: pointer;
  padding: 6px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: color var(--transition-fast), background-color var(--transition-fast);
}

.expense-delete-btn:hover {
  color: var(--accent-danger);
  background-color: #fee2e2;
}

/* 新規追加フォーム */
.add-form-card {
  background-color: var(--bg-surface);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.form-row {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

@media (min-width: 640px) {
  .form-row {
    grid-template-columns: 2fr 1.5fr 1fr auto;
    align-items: flex-end;
  }
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.form-label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted);
}

.form-input,
.form-select {
  height: 42px;
  padding: 0 12px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background-color: var(--bg-surface);
  color: var(--text-main);
  font-size: 0.95rem;
  font-family: inherit;
  outline: none;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.form-input:focus,
.form-select:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.form-input::placeholder {
  color: var(--text-light);
}

.btn-submit {
  height: 42px;
  padding: 0 20px;
  background-color: var(--accent-primary);
  color: #ffffff;
  border: none;
  border-radius: var(--radius-sm);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  white-space: nowrap;
  transition: background-color var(--transition-fast), transform var(--transition-fast);
}

.btn-submit:hover {
  background-color: var(--accent-primary-hover);
}

.btn-submit:active {
  transform: scale(0.98);
}

/* 空の状態表示 */
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 32px 16px;
  color: var(--text-muted);
  gap: 8px;
  text-align: center;
}

.empty-state svg {
  color: var(--text-light);
  margin-bottom: 4px;
}

export interface ExpenseItem {
  id: string;
  name: string;
  amount: number;
  color: string;
  icon: string;
}

export interface CategoryPreset {
  name: string;
  icon: string;
  color: string;
}

export interface ChartActiveShapeProps {
  cx?: number;
  cy?: number;
  midAngle?: number;
  innerRadius?: number;
  outerRadius?: number;
  startAngle?: number;
  endAngle?: number;
  fill?: string;
  payload?: ExpenseItem;
  percent?: number;
  value?: number;
  [key: string]: any;
}

export interface ExpenseListProps {
  items: ExpenseItem[];
  selectedId: string | null;
  onSelect: (id: string) => void;
  onDelete: (id: string) => void;
}

export interface ExpenseChartProps {
  items: ExpenseItem[];
  selectedId: string | null;
  onSelect: (id: string) => void;
}

import { useMemo } from 'react';
import { ResponsiveContainer, PieChart, Pie, Cell, Sector } from 'recharts';
import { PieChart as PieChartIcon } from 'lucide-react';
import { ExpenseChartProps, ChartActiveShapeProps } from '../types';
import { formatCurrency } from '../utils/formatters';

const renderActiveShape = (props: ChartActiveShapeProps) => {
  const {
    cx = 0,
    cy = 0,
    innerRadius = 0,
    outerRadius = 0,
    startAngle = 0,
    endAngle = 0,
    fill = '#3b82f6',
  } = props;

  return (
    <g>
      <Sector
        cx={cx}
        cy={cy}
        innerRadius={innerRadius - 4}
        outerRadius={outerRadius + 8}
        startAngle={startAngle}
        endAngle={endAngle}
        fill={fill}
        style={{
          filter: 'drop-shadow(0px 4px 8px rgba(0, 0, 0, 0.18))',
          transition: 'all 0.3s ease',
          cursor: 'pointer',
        }}
      />
      <Sector
        cx={cx}
        cy={cy}
        innerRadius={innerRadius - 8}
        outerRadius={innerRadius - 4}
        startAngle={startAngle}
        endAngle={endAngle}
        fill={fill}
        opacity={0.4}
      />
    </g>
  );
};

export default function ExpenseChart({
  items = [],
  selectedId,
  onSelect,
}: ExpenseChartProps) {
  const totalAmount = useMemo(() => {
    return items.reduce((sum, item) => sum + item.amount, 0);
  }, [items]);

  const activeIndex = useMemo(() => {
    if (!selectedId) return -1;
    return items.findIndex((item) => item.id === selectedId);
  }, [items, selectedId]);

  const selectedItem = useMemo(() => {
    if (!selectedId) return null;
    return items.find((item) => item.id === selectedId) || null;
  }, [items, selectedId]);

  const selectedRatio = useMemo(() => {
    if (!selectedItem || totalAmount === 0) return 0;
    return Math.round((selectedItem.amount / totalAmount) * 1000) / 10;
  }, [selectedItem, totalAmount]);

  if (items.length === 0) {
    return (
      <div className="empty-state">
        <PieChartIcon size={48} />
        <p>支出データがありません</p>
        <span className="hint-text">下のフォームから支出を追加してください</span>
      </div>
    );
  }

  return (
    <>
      <div className="chart-wrapper">
        <ResponsiveContainer width="100%" height={320}>
          <PieChart>
            <Pie
              activeIndex={activeIndex >= 0 ? activeIndex : undefined}
              activeShape={renderActiveShape}
              data={items}
              cx="50%"
              cy="50%"
              innerRadius={70}
              outerRadius={105}
              paddingAngle={3}
              dataKey="amount"
              onClick={(_, index) => {
                if (typeof index === 'number' && items[index]) {
                  onSelect?.(items[index].id);
                }
              }}
              style={{ outline: 'none', cursor: 'pointer' }}
            >
              {items.map((entry) => (
                <Cell
                  key={`cell-${entry.id}`}
                  fill={entry.color}
                  stroke="#ffffff"
                  strokeWidth={2}
                />
              ))}
            </Pie>
            <text
              x="50%"
              y="46%"
              textAnchor="middle"
              dominantBaseline="middle"
              fill="#64748b"
              fontSize="12"
              fontWeight="500"
              style={{ cursor: selectedId ? 'pointer' : 'default' }}
              onClick={() => {
                if (selectedId) {
                  onSelect?.(selectedId);
                }
              }}
            >
              {selectedItem ? '選択中' : '総支出'}
            </text>
            <text
              x="50%"
              y="55%"
              textAnchor="middle"
              dominantBaseline="middle"
              fill="#0f172a"
              fontSize="15"
              fontWeight="700"
              style={{ cursor: selectedId ? 'pointer' : 'default' }}
              onClick={() => {
                if (selectedId) {
                  onSelect?.(selectedId);
                }
              }}
            >
              {selectedItem
                ? formatCurrency(selectedItem.amount)
                : formatCurrency(totalAmount)}
            </text>
          </PieChart>
        </ResponsiveContainer>
      </div>

      <p className="hint-text">
        円グラフのセクターをクリックすると詳細が切り替わります
      </p>

      {selectedItem ? (
        <div className="selected-info-card">
          <div className="selected-info-header">
            <div className="selected-name">
              <span>{selectedItem.icon}</span>
              <span>{selectedItem.name}</span>
            </div>
            <div className="selected-ratio">全体比 {selectedRatio}%</div>
          </div>
          <div className="selected-amount">
            {formatCurrency(selectedItem.amount)}
          </div>
        </div>
      ) : (
        <div className="selected-info-card">
          <div className="selected-info-header">
            <div className="selected-name">
              <span>💡</span>
              <span>項目を選択してください</span>
            </div>
            <div className="selected-ratio">未選択</div>
          </div>
          <div className="selected-empty-hint">
            グラフまたはリストを押すと詳細が表示されます
          </div>
        </div>
      )}
    </>
  );
}

import { useMemo } from 'react';
import { Trash2, AlertCircle } from 'lucide-react';
import { ExpenseListProps } from '../types';
import { formatCurrency } from '../utils/formatters';

export default function ExpenseList({
  items = [],
  selectedId,
  onSelect,
  onDelete,
}: ExpenseListProps) {
  const totalAmount = useMemo(() => {
    return items.reduce((sum, item) => sum + item.amount, 0);
  }, [items]);

  if (items.length === 0) {
    return (
      <div className="empty-state">
        <AlertCircle size={40} />
        <p>登録された項目はありません</p>
      </div>
    );
  }

  return (
    <div className="expense-list">
      {items.map((item) => {
        const isSelected = item.id === selectedId;
        const ratio =
          totalAmount > 0
            ? Math.round((item.amount / totalAmount) * 1000) / 10
            : 0;

        return (
          <div
            key={item.id}
            className={isSelected ? 'expense-card expense-card-active' : 'expense-card'}
            onClick={() => onSelect?.(item.id)}
            role="button"
            tabIndex={0}
            aria-pressed={isSelected}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                onSelect?.(item.id);
              }
            }}
          >
            <div
              className="expense-icon-badge"
              style={{ backgroundColor: `${item.color}1a` }}
            >
              <span>{item.icon}</span>
            </div>

            <div className="expense-details">
              <span className="expense-name">{item.name}</span>
              <span className="expense-ratio">構成比 {ratio}%</span>
            </div>

            <span className="expense-amount">
              {formatCurrency(item.amount)}
            </span>

            <button
              type="button"
              className="expense-delete-btn"
              title="削除"
              aria-label={`${item.name}を削除`}
              onClick={(e) => {
                e.stopPropagation();
                if (window.confirm(`「${item.name}」を削除してもよろしいですか？`)) {
                  onDelete?.(item.id);
                }
              }}
            >
              <Trash2 size={16} />
            </button>
          </div>
        );
      })}
    </div>
  );
}

import { useState, useMemo, FormEvent } from 'react';
import { Wallet, PlusCircle } from 'lucide-react';
import { ExpenseItem } from './types';
import { CATEGORY_PRESETS, INITIAL_EXPENSES, MAX_EXPENSE_AMOUNT } from './constants';
import ExpenseChart from './components/ExpenseChart';
import ExpenseList from './components/ExpenseList';

const generateUniqueId = (): string => {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
};

export default function App() {
  const [items, setItems] = useState<ExpenseItem[]>(INITIAL_EXPENSES);
  const [selectedId, setSelectedId] = useState<string | null>('1');

  // フォーム用ステート
  const [formCategoryIndex, setFormCategoryIndex] = useState<number>(0);
  const [customName, setCustomName] = useState<string>('');
  const [formAmount, setFormAmount] = useState<string>('');

  const totalAmount = useMemo(() => {
    return items.reduce((sum, item) => sum + item.amount, 0);
  }, [items]);

  const handleSelect = (id: string) => {
    setSelectedId((prev) => (prev === id ? null : id));
  };

  const handleDelete = (id: string) => {
    setItems((prev) => prev.filter((item) => item.id !== id));
    if (selectedId === id) {
      setSelectedId(null);
    }
  };

  const handleAddItem = (e: FormEvent) => {
    e.preventDefault();
    const parsedAmount = parseInt(formAmount, 10);
    if (isNaN(parsedAmount) || parsedAmount <= 0 || parsedAmount > MAX_EXPENSE_AMOUNT) {
      return;
    }

    const preset = CATEGORY_PRESETS[formCategoryIndex] || CATEGORY_PRESETS[0];
    const finalName = customName.trim() || preset.name;

    const newItem: ExpenseItem = {
      id: generateUniqueId(),
      name: finalName,
      amount: parsedAmount,
      color: preset.color,
      icon: preset.icon,
    };

    setItems((prev) => [...prev, newItem]);
    setSelectedId(newItem.id);

    // リセット
    setCustomName('');
    setFormAmount('');
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="header-title">
          <Wallet size={28} />
          家計支出ダッシュボード
        </h1>
        <p className="header-subtitle">
          支出の内訳を直感的に把握・管理できるインタラクティブ円グラフ
        </p>
      </header>

      <div className="total-card">
        <span className="total-label">今月の総支出</span>
        <div className="total-amount">
          ¥{totalAmount.toLocaleString()}
        </div>
      </div>

      <div className="main-layout">
        <section className="chart-section">
          <h2 className="list-title">支出割合グラフ</h2>
          <ExpenseChart
            items={items}
            selectedId={selectedId}
            onSelect={handleSelect}
          />
        </section>

        <section className="list-section">
          <div className="list-header">
            <h2 className="list-title">支出明細一覧 ({items.length}件)</h2>
          </div>
          <ExpenseList
            items={items}
            selectedId={selectedId}
            onSelect={handleSelect}
            onDelete={handleDelete}
          />
        </section>
      </div>

      <div className="add-form-card">
        <h2 className="list-title">支出項目の新規追加</h2>
        <form onSubmit={handleAddItem}>
          <div className="form-row">
            <div className="form-group">
              <label className="form-label" htmlFor="expense-category">
                カテゴリ
              </label>
              <select
                id="expense-category"
                className="form-select"
                value={formCategoryIndex}
                onChange={(e) => {
                  const idx = parseInt(e.target.value, 10);
                  setFormCategoryIndex(idx);
                }}
              >
                {CATEGORY_PRESETS.map((preset, idx) => (
                  <option key={preset.name} value={idx}>
                    {preset.icon} {preset.name}
                  </option>
                ))}
              </select>
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="expense-name">
                項目名（任意）
              </label>
              <input
                id="expense-name"
                type="text"
                className="form-input"
                placeholder={CATEGORY_PRESETS[formCategoryIndex]?.name || '食費'}
                value={customName}
                onChange={(e) => setCustomName(e.target.value)}
              />
            </div>

            <div className="form-group">
              <label className="form-label" htmlFor="expense-amount">
                金額（円）
              </label>
              <input
                id="expense-amount"
                type="number"
                min="1"
                max={MAX_EXPENSE_AMOUNT.toString()}
                step="1"
                required
                className="form-input"
                placeholder="例: 15000"
                value={formAmount}
                onChange={(e) => setFormAmount(e.target.value)}
              />
            </div>

            <button type="submit" className="btn-submit">
              <PlusCircle size={18} />
              <span>追加</span>
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

export const formatCurrency = (amount: number): string => {
  return `¥${new Intl.NumberFormat('ja-JP').format(amount)}`;
};
